WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_rt_b_simplify'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '化简与通分', 'kp-rt-b-simplify', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "比例化简与通分"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "将 A:B 和 B:C 两个独立的比例，桥接成 A:B:C。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲是乙的 3/4，乙是丙的 2/5。求甲丙比例？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心战法：找公共锚点"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "乙是两者的公共桥梁。第一组乙是 4，第二组乙是 2。找 4 和 2 的最小公倍数 4。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "第一组不需要动：甲:乙 = 3:4。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "第二组上下乘 2：乙:丙 = 4:10。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "拼接：甲:乙:丙 = 3:4:10。所以甲:丙 = 3:10。"}]}]}$$ AS jsonb), NULL, '化简与通分的核心考点与实战推导。', category_node.id, CAST('["数量关系", "化简与通分"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_rt_b_simplify", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
